test('lateFee accumulates over multiple days', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const totals = invoiceTotals(issued);

  const fee4Days = lateFee(issued, '2026-10-25');
  const fee14Days = lateFee(issued, '2026-11-04');

  // fee should increase with more days overdue
  assert.ok(fee14Days > fee4Days);
  assert.equal(fee4Days, Math.round(totals.total * 4 * 0.04 / 100));
  assert.equal(fee14Days, Math.round(totals.total * 14 * 0.04 / 100));
});

